cat > /tmp/inspect_agents.csx << 'EOF'
using System;
using System.Reflection;

// Load the assembly
var dll = Assembly.LoadFrom("/home/runner/.nuget/packages/microsoft.agents.ai/1.10.0/lib/net8.0/Microsoft.Agents.AI.dll");

Console.WriteLine("=== Microsoft.Agents.AI Types ===\n");

// Get all types in the namespace
var types = dll.GetTypes()
    .Where(t => t.Namespace == "Microsoft.Agents.AI")
    .OrderBy(t => t.Name)
    .ToList();

Console.WriteLine($"Found {types.Count} types in Microsoft.Agents.AI namespace:\n");

foreach (var type in types)
{
    if (type.IsClass || type.IsInterface)
    {
        Console.WriteLine($"\n{(type.IsInterface ? "INTERFACE" : "CLASS")}: {type.Name}");
        if (type.BaseType != null && type.BaseType != typeof(object))
        {
            Console.WriteLine($"  Base: {type.BaseType.Name}");
        }

        // Constructors
        var constructors = type.GetConstructors(BindingFlags.Public | BindingFlags.Instance);
        if (constructors.Length > 0)
        {
            Console.WriteLine($"  Constructors:");
            foreach (var ctor in constructors)
            {
                var @params = string.Join(", ", ctor.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
                Console.WriteLine($"    public {type.Name}({@params})");
            }
        }

        // Methods
        var methods = type.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly);
        if (methods.Length > 0)
        {
            Console.WriteLine($"  Methods:");
            foreach (var method in methods)
            {
                var @params = string.Join(", ", method.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
                Console.WriteLine($"    public {method.ReturnType.Name} {method.Name}({@params})");
            }
        }

        // Properties
        var properties = type.GetProperties(BindingFlags.Public | BindingFlags.Instance);
        if (properties.Length > 0)
        {
            Console.WriteLine($"  Properties:");
            foreach (var prop in properties)
            {
                Console.WriteLine($"    public {prop.PropertyType.Name} {prop.Name} {{ {(prop.CanRead ? "get; " : "")}{(prop.CanWrite ? "set; " : "")}}}");
            }
        }
    }
}
