using System;
using System.Reflection;
using System.Linq;

class Program
{
    static void Main()
    {
        try
        {
            // Load Microsoft.Extensions.AI
            var meaiDll = Assembly.LoadFrom("/home/runner/.nuget/packages/microsoft.extensions.ai/10.6.0/lib/net8.0/Microsoft.Extensions.AI.dll");

            Console.WriteLine("=== Microsoft.Extensions.AI Key Types ===\n");

            // Find AITool, AIFunction, ChatOptions
            var types = meaiDll.GetTypes()
                .Where(t => t.Namespace == "Microsoft.Extensions.AI" && 
                           (t.Name.Contains("AITool") || 
                            t.Name.Contains("AIFunction") || 
                            t.Name == "ChatOptions" ||
                            t.Name == "ChatMessage"))
                .OrderBy(t => t.Name)
                .ToList();

            foreach (var type in types)
            {
                Console.WriteLine($"\n{type.Name}:");
                if (type.IsEnum)
                    Console.WriteLine("  [ENUM]");
                else if (type.IsValueType)
                    Console.WriteLine("  [STRUCT]");
                else if (type.IsInterface)
                    Console.WriteLine("  [INTERFACE]");
                else
                    Console.WriteLine("  [CLASS]");

                // Properties
                var properties = type.GetProperties(BindingFlags.Public | BindingFlags.Instance);
                if (properties.Length > 0)
                {
                    foreach (var prop in properties.Take(10))
                    {
                        Console.WriteLine($"    {prop.PropertyType.Name} {prop.Name}");
                    }
                    if (properties.Length > 10)
                        Console.WriteLine($"    ... and {properties.Length - 10} more");
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }
}
