using System;
using System.Reflection;
using System.Linq;
using Microsoft.Extensions.AI;

class Program
{
    static void Main()
    {
        Console.WriteLine("=== Microsoft.Extensions.AI Key Types ===\n");

        // Get AITool type
        var aiToolType = typeof(Microsoft.Extensions.AI.AITool);
        Console.WriteLine($"AITool:");
        Console.WriteLine($"  Type: {(aiToolType.IsValueType ? "STRUCT" : "CLASS")}");
        ShowTypeMembers(aiToolType);

        // Try to find related types
        var asm = typeof(AITool).Assembly;
        var relatedTypes = asm.GetTypes()
            .Where(t => t.Namespace == "Microsoft.Extensions.AI" && 
                       (t.Name.Contains("AIFunction") || t.Name.Contains("ChatOptions")))
            .OrderBy(t => t.Name);

        foreach (var type in relatedTypes.Take(10))
        {
            Console.WriteLine($"\n{type.Name}:");
            Console.WriteLine($"  Type: {(type.IsValueType ? "STRUCT" : type.IsInterface ? "INTERFACE" : "CLASS")}");
            ShowTypeMembers(type);
        }
    }

    static void ShowTypeMembers(Type type)
    {
        var props = type.GetProperties(BindingFlags.Public | BindingFlags.Instance);
        if (props.Length > 0)
        {
            foreach (var prop in props.Take(8))
            {
                var getset = "";
                if (prop.CanRead) getset += "get ";
                if (prop.CanWrite) getset += "set";
                Console.WriteLine($"    {prop.PropertyType.Name} {prop.Name} {{ {getset} }}");
            }
        }

        var methods = type.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly)
            .Where(m => !m.Name.StartsWith("get_") && !m.Name.StartsWith("set_"))
            .Take(5);
        foreach (var method in methods)
        {
            var plist = string.Join(", ", method.GetParameters().Select(p => p.ParameterType.Name));
            Console.WriteLine($"    {method.ReturnType.Name} {method.Name}({plist})");
        }
    }
}
