using System;
using System.Reflection;
using System.Linq;
using Microsoft.Agents.AI;

class Program
{
    static void Main()
    {
        Console.WriteLine("=== Microsoft.Agents.AI ChatClientAgent ===\n");

        var agentType = typeof(Microsoft.Agents.AI.ChatClientAgent);

        // Constructors
        Console.WriteLine("CONSTRUCTORS:");
        var ctors = agentType.GetConstructors(BindingFlags.Public);
        foreach (var ctor in ctors)
        {
            var @params = string.Join(", ", ctor.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
            Console.WriteLine($"  public ChatClientAgent({@params})");
        }

        // Methods
        Console.WriteLine("\nKEY METHODS:");
        var runMethods = agentType.GetMethods(BindingFlags.Public | BindingFlags.Instance)
