using System.ComponentModel;
using System.Text.Json;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides web search capabilities for the research agent.
/// Uses a simple HTTP-based approach to fetch and extract content from the web.
/// Replace the SearchAsync implementation with a real search API (e.g., Bing Search)
/// for production use.
/// </summary>
public sealed class WebSearchTool
{
    private readonly HttpClient _httpClient;

    public WebSearchTool(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [Description("Searches the web for information on a given query. Returns a list of search result snippets.")]
    public async Task<string> SearchAsync(
        [Description("The search query to look up on the web")] string query,
        CancellationToken cancellationToken = default)
    {
        try
        {
            // Use DuckDuckGo Instant Answer API (no API key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

            var response = await _httpClient.GetStringAsync(url, cancellationToken);
            var doc = JsonDocument.Parse(response);
            var root = doc.RootElement;

            var results = new List<string>();

            // Extract the abstract/summary if available
            var abstractText = root.GetProperty("Abstract").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                var source = root.GetProperty("AbstractSource").GetString();
                results.Add($"[{source}] {abstractText}");
            }

            // Extract related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text))
                    {
                        var snippet = text.GetString();
                        if (!string.IsNullOrWhiteSpace(snippet))
                        {
                            results.Add(snippet);
                        }
                    }
                }
            }

            // Extract answer if available
            var answer = root.GetProperty("Answer").GetString();
            if (!string.IsNullOrWhiteSpace(answer))
            {
                results.Add($"[Direct Answer] {answer}");
            }

            if (results.Count == 0)
            {
                return $"No results found for '{query}'. Try rephrasing your search.";
            }

            return string.Join("\n\n", results);
        }
        catch (HttpRequestException ex)
        {
            return $"Search failed for '{query}': {ex.Message}. Try a different query.";
        }
    }
}

using System.ComponentModel;
using System.Text;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides note-taking capabilities for the research agent to organize findings.
/// Notes are stored in memory for the duration of the research session.
/// </summary>
public sealed class NoteTakingTool
{
    private readonly List<(string Topic, string Content, DateTime Timestamp)> _notes = [];

    [Description("Saves a research note with a topic label and content. Use this to record key findings during research.")]
    public string AddNote(
        [Description("A short topic label for the note (e.g., 'Definition', 'Key Statistics', 'History')")] string topic,
        [Description("The content of the note — a fact, quote, or insight to remember")] string content)
    {
        _notes.Add((topic, content, DateTime.UtcNow));
        return $"Note #{_notes.Count} saved under '{topic}'.";
    }

    [Description("Retrieves all saved research notes, organized by topic.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been saved yet.";
        }

        var sb = new StringBuilder();
        sb.AppendLine($"=== Research Notes ({_notes.Count} total) ===");

        var grouped = _notes.GroupBy(n => n.Topic);
        foreach (var group in grouped)
        {
            sb.AppendLine($"\n## {group.Key}");
            foreach (var (_, content, timestamp) in group)
            {
                sb.AppendLine($"  - {content}");
            }
        }

        return sb.ToString();
    }

    [Description("Clears all saved notes to start fresh.")]
    public string ClearNotes()
    {
        var count = _notes.Count;
        _notes.Clear();
        return $"Cleared {count} note(s).";
    }
}

