using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;
using ResearchAgent.Tools;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to your OpenAI API key.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Services ---
var services = new ServiceCollection();

services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));

services.AddHttpClient<WebSearchTool>(client =>
{
    client.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");
    client.Timeout = TimeSpan.FromSeconds(15);
});

services.AddSingleton<NoteTakingTool>();

services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

var provider = services.BuildServiceProvider();

// --- Tools ---
var searchTool = provider.GetRequiredService<WebSearchTool>();
var noteTool = provider.GetRequiredService<NoteTakingTool>();
var chatClient = provider.GetRequiredService<IChatClient>();
var loggerFactory = provider.GetRequiredService<ILoggerFactory>();

var tools = new AITool[]
{
    AIFunctionFactory.Create(searchTool.SearchAsync),
    AIFunctionFactory.Create(noteTool.AddNote),
    AIFunctionFactory.Create(noteTool.GetNotes),
    AIFunctionFactory.Create(noteTool.ClearNotes),
};

// --- Prompt for topic ---
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\n🔍 Researching: {topic}\n");

// --- Create and run the agent ---
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a thorough research agent. Your job is to research a topic using web search,
        take organized notes on your findings, and then produce a clear summary.

        Follow this process:
        1. Search the web with 2-3 different queries to gather diverse information
        2. After each search, save the most important findings as notes with descriptive topic labels
        3. Once you have gathered enough information, retrieve all your notes
        4. Write a well-structured summary that synthesizes your findings

        Guidelines:
        - Use varied search queries to cover different angles of the topic
        - Take concise but informative notes
        - Your final summary should be comprehensive yet readable
        - Cite the sources of information where possible
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics using web search and note-taking",
    tools: tools,
    loggerFactory: loggerFactory,
    services: provider);

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
});

var session = new ChatClientAgentSession();

var response = await agent.RunAsync(
    $"Please research the following topic and provide a comprehensive summary: {topic}",
    session,
    runOptions,
    CancellationToken.None);

// --- Display results ---
Console.WriteLine("\n" + new string('═', 60));
Console.WriteLine("  RESEARCH SUMMARY");
Console.WriteLine(new string('═', 60) + "\n");

foreach (var message in response.Messages)
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
    {
        Console.WriteLine(message.Text);
    }
}

Console.WriteLine("\n" + new string('═', 60));

using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;
using ResearchAgent.Tools;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to your OpenAI API key.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Services ---
var services = new ServiceCollection();

services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));

services.AddHttpClient<WebSearchTool>(client =>
{
    client.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");
    client.Timeout = TimeSpan.FromSeconds(15);
});

services.AddSingleton<NoteTakingTool>();

services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

var provider = services.BuildServiceProvider();

// --- Tools ---
var searchTool = provider.GetRequiredService<WebSearchTool>();
var noteTool = provider.GetRequiredService<NoteTakingTool>();
var chatClient = provider.GetRequiredService<IChatClient>();
var loggerFactory = provider.GetRequiredService<ILoggerFactory>();

var tools = new AITool[]
{
    AIFunctionFactory.Create(searchTool.SearchAsync),
    AIFunctionFactory.Create(noteTool.AddNote),
    AIFunctionFactory.Create(noteTool.GetNotes),
    AIFunctionFactory.Create(noteTool.ClearNotes),
};

// --- Prompt for topic ---
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\n🔍 Researching: {topic}\n");

// --- Create and run the agent ---
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a thorough research agent. Your job is to research a topic using web search,
        take organized notes on your findings, and then produce a clear summary.

        Follow this process:
        1. Search the web with 2-3 different queries to gather diverse information
        2. After each search, save the most important findings as notes with descriptive topic labels
        3. Once you have gathered enough information, retrieve all your notes
        4. Write a well-structured summary that synthesizes your findings

        Guidelines:
        - Use varied search queries to cover different angles of the topic
        - Take concise but informative notes
        - Your final summary should be comprehensive yet readable
        - Cite the sources of information where possible
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics using web search and note-taking",
    tools: tools,
    loggerFactory: loggerFactory,
    services: provider);

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
});

var session = new ChatClientAgentSession();

var response = await agent.RunAsync(
    $"Please research the following topic and provide a comprehensive summary: {topic}",
    session,
    runOptions,
    CancellationToken.None);

// --- Display results ---
Console.WriteLine("\n" + new string('═', 60));
Console.WriteLine("  RESEARCH SUMMARY");
Console.WriteLine(new string('═', 60) + "\n");

foreach (var message in response.Messages)
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
    {
        Console.WriteLine(message.Text);
    }
}

Console.WriteLine("\n" + new string('═', 60));

